package com.rezoxnemesis.videostudio;
import android.app.*;import android.os.*;import android.widget.*;import org.json.*;
public final class AssistApprovalActivity extends Activity {
    @Override public void onCreate(Bundle b){super.onCreate(b);draw();}
    private void draw(){AssistApprovalStore store=new AssistApprovalStore(this);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(20,20,20,20);ScrollView scroll=new ScrollView(this);scroll.addView(root);setContentView(scroll);TextView title=new TextView(this);title.setText("ChatGPT Assist · pending approvals");title.setTextSize(22);root.addView(title);JSONArray items=store.list();int pending=0;for(int i=0;i<items.length();i++){JSONObject item=items.optJSONObject(i);if(item==null||item.optBoolean("used")||item.optLong("expiresAt")<System.currentTimeMillis())continue;pending++;Button row=new Button(this);row.setText(item.optString("action")+(item.optBoolean("approved")?" · approved, awaiting retry":" · review"));row.setOnClickListener(v->{String details;try{details=item.getJSONObject("parameters").toString(2);}catch(Exception e){details="Invalid request";}new AlertDialog.Builder(this).setTitle(item.optString("action")).setMessage(details+"\n\nApproval allows one matching retry within ten minutes. ChatGPT must retry with this approval ID: "+item.optString("id")).setPositiveButton("Approve once",(d,w)->{try{store.decide(item.getString("id"),true);draw();}catch(Exception ignored){}}).setNegativeButton("Reject",(d,w)->{try{store.decide(item.getString("id"),false);draw();}catch(Exception ignored){}}).show();});root.addView(row);}if(pending==0){TextView empty=new TextView(this);empty.setText("No pending requests. Choose ChatGPT Assist in Control to require approval for project changes.");root.addView(empty);}Button close=new Button(this);close.setText("Back");close.setOnClickListener(v->finish());root.addView(close);}
}
